#!/usr/bin/env python3
# Exact reconstruction of the input convention of artifact
# 621a26ec7b4419d76351b43e22fff9df644945c6458e2a531d2542a0819b6602:
# partitions in [222,5^5], reverse-lexicographic ambient order; relation
# rows ordered by h-degree 1,...,5 then reverse-lexicographic source order.
import hashlib

LOW=(2,2,2,0,0); UP=(5,5,5,5,5)
GL={6:['222'],7:['2221'],8:['2222','22211'],9:['22221'],10:['22222']}
GR={6:['222'],7:['322'],8:['422','332'],9:['432'],10:['442']}
EXPECT={6:[[1]],7:[[-1]],8:[[0,1],[1,0]],9:[[-1]],10:[[1]]}

def wt(p): return sum(p)
def label(p): return ''.join(map(str,[x for x in p if x])) or '0'
def parts(d):
    out=[]
    def rec(i,last,left,a):
        if i==5:
            if left==0 and all(a[j]>=LOW[j] for j in range(5)): out.append(tuple(a))
            return
        lo=LOW[i]; hi=min(last,UP[i],left)
        for x in range(hi,lo-1,-1): rec(i+1,x,left-x,a+[x])
    rec(0,UP[0],d,[])
    return out # already reverse lexicographic

def horiz(lam,mu):
    # mu/lam horizontal iff interlacing mu_1>=lam_1>=mu_2>=lam_2>=...
    return all(mu[i]>=lam[i] and (i==4 or lam[i]>=mu[i+1]) for i in range(5))

def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def matmul(A,B):
    if not A: return [[] for _ in range(len(A))]
    if not B: return [[] for _ in range(len(A))]
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def trans(A): return [list(x) for x in zip(*A)] if A else []
def eq(A,B): return A==B
def fmt(A): return '['+'; '.join('['+','.join(map(str,r))+']' for r in A)+']'
def det(A):
    n=len(A)
    if n==0:return 1
    B=[r[:] for r in A]; s=1; prev=1
    for k in range(n-1):
        q=next((i for i in range(k,n) if B[i][k]),None)
        if q is None:return 0
        if q!=k:B[k],B[q]=B[q],B[k];s=-s
        piv=B[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n): B[i][j]=(B[i][j]*piv-B[i][k]*B[k][j])//prev
        prev=piv
        for i in range(k+1,n):B[i][k]=0
    return s*B[-1][-1]
def inv_unimod(A):
    n=len(A); B=[A[i][:]+eye(n)[i] for i in range(n)]
    for k in range(n):
        q=next(i for i in range(k,n) if abs(B[i][k])==1)
        B[k],B[q]=B[q],B[k]
        if B[k][k]==-1:B[k]=[-x for x in B[k]]
        for i in range(n):
            if i!=k:
                q=B[i][k]
                B[i]=[B[i][j]-q*B[k][j] for j in range(2*n)]
    return [r[n:] for r in B]

def smith(M):
    m=len(M); n=len(M[0]) if m else 0
    A=[r[:] for r in M]; U=eye(m); V=eye(n)
    def rswap(i,j):
        A[i],A[j]=A[j],A[i];U[i],U[j]=U[j],U[i]
    def cswap(i,j):
        for X in (A,V):
            if X is A:
                for r in X:r[i],r[j]=r[j],r[i]
            else:
                for r in X:r[i],r[j]=r[j],r[i]
    def radd(i,j,q):
        A[i]=[x+q*y for x,y in zip(A[i],A[j])];U[i]=[x+q*y for x,y in zip(U[i],U[j])]
    def cadd(i,j,q):
        for r in A:A[r.__class__ is list and 0 or 0] if False else []
        for r in A:r[i]+=q*r[j]
        for r in V:r[i]+=q*r[j]
    k=0
    while k<m and k<n:
        nz=[(abs(A[i][j]),i,j) for i in range(k,m) for j in range(k,n) if A[i][j]]
        if not nz: break
        _,i,j=min(nz); rswap(k,i); cswap(k,j)
        while True:
            changed=False
            for i in range(k+1,m):
                if A[i][k]:
                    q=A[i][k]//A[k][k]
                    radd(i,k,-q)
                    if A[i][k]: rswap(i,k)
                    changed=True; break
            if changed: continue
            for j in range(k+1,n):
                if A[k][j]:
                    q=A[k][j]//A[k][k]
                    cadd(j,k,-q)
                    if A[k][j]: cswap(j,k)
                    changed=True; break
            if changed: continue
            bad=next(((i,j) for i in range(k+1,m) for j in range(k+1,n) if A[i][j]%A[k][k]),None)
            if bad is None: break
            # introduce A[i,j] into pivot row, then Euclidean-reduce its column
            radd(k,bad[0],1)
        if A[k][k]<0:
            U[k]=[-x for x in U[k]];A[k]=[-x for x in A[k]]
        k+=1
    return U,A,V,k

def selection(B,names):
    return [[int(label(p)==x) for x in names] for p in B]

allok=True
for d in range(6,11):
    B=parts(d); index={p:i for i,p in enumerate(B)}
    rows=[]; rownames=[]
    for t in range(1,6):
        for lam in parts(d-t):
            row=[int(horiz(lam,mu)) for mu in B]
            rows.append(row); rownames.append('h%d*%s'%(t,label(lam)))
    M=rows; U,D,V,r=smith(M)
    # quotient coordinates from final Smith zero-coordinate rows, normalized on L
    Vinv=inv_unimod(V)
    C0=[Vinv[i][:] for i in range(r,len(B))]
    L=selection(B,GL[d]); R=selection(B,GR[d])
    CL=matmul(C0,L)
    C=matmul(inv_unimod(CL),C0)
    T=matmul(C,R)
    zrows=len(M); zcols=len(B)
    lhs=matmul(matmul(U,M),V)
    cm=matmul(C,trans(M)) if M else [[] for _ in C]
    zeroCM=[[0]*zrows for _ in C]
    I=eye(len(GL[d]))
    nonzero=[D[i][i] for i in range(min(len(D),len(B))) if D[i][i]!=0]
    ok=(eq(lhs,D) and eq(cm,zeroCM) and eq(matmul(C,L),I) and eq(T,EXPECT[d])
        and abs(det(U))==1 and abs(det(V))==1 and all(x==1 for x in nonzero))
    allok &= ok
    print('SOURCE_ARTIFACT=621a26ec7b4419d76351b43e22fff9df644945c6458e2a531d2542a0819b6602')
    print('DEGREE',d)
    print('B='+str([label(p) for p in B]))
    print('ROWS='+str(rownames))
    print('M='+fmt(M)); print('U='+fmt(U)); print('V='+fmt(V)); print('D='+fmt(D))
    print('C='+fmt(C)); print('L='+fmt(L)); print('R='+fmt(R)); print('T='+fmt(T))
    print('VERIFY U*M*V=D:',eq(lhs,D),'C*M^T=0:',eq(cm,zeroCM),'C*L=I:',eq(matmul(C,L),I),'C*R=T:',eq(T,EXPECT[d]),'detU=',det(U),'detV=',det(V),'ones=',all(x==1 for x in nonzero),'EXPECTED_T=',fmt(EXPECT[d]),'PASS=',ok)
assert allok
